const rows = (name) => $(name).all().map(i => i.json).filter(p => p && p.id && p.properties);
const weekly = rows('Get Weekly Items');
const tasks = rows('Get Tasks');
const subs = rows('Get Subtasks');
const key = (id) => id.replace(/-/g, '');

const status = new Map();
const edited = new Map();
const title = new Map();
for (const [list, table] of [[weekly, 'Weekly Plan'], [tasks, 'Tasks'], [subs, 'Subtasks']]) {
  for (const p of list) {
    const id = key(p.id);
    status.set(id, p.properties.Status?.select?.name ?? null);
    edited.set(id, p.last_edited_time);
    const t = Object.values(p.properties).find((v) => v.type === 'title');
    title.set(id, `${table}: ${(t?.title ?? []).map((x) => x.plain_text).join('')}`);
  }
}

const kids = new Map();
const link = (children, relProp) => {
  for (const c of children) {
    for (const r of c.properties[relProp]?.relation ?? []) {
      const parent = key(r.id);
      if (!kids.has(parent)) kids.set(parent, []);
      kids.get(parent).push(key(c.id));
    }
  }
};
link(tasks, 'Weekly Item');
link(subs, 'Task');

const closed = (s) => s === 'Done' || s === 'Cancelled';
const changes = new Map();
const set = (id, s, reason) => {
  if (status.get(id) === s) return;
  status.set(id, s);
  edited.set(id, new Date().toISOString());
  changes.set(id, { page_id: id, status: s, name: title.get(id), reason });
};

// Down: a closed parent closes its open children, unless a child was edited after the parent.
const down = (parents) => {
  for (const p of parents) {
    const id = key(p.id);
    const s = status.get(id);
    if (!closed(s)) continue;
    for (const c of kids.get(id) ?? []) {
      if (!closed(status.get(c)) && edited.get(id) >= edited.get(c)) set(c, s, `parent ${title.get(id)} is ${s}`);
    }
  }
};

// Up: all children closed (at least one Done) completes the parent, unless the parent was edited after its newest child.
const up = (parents) => {
  for (const p of parents) {
    const id = key(p.id);
    const k = kids.get(id) ?? [];
    if (!k.length || closed(status.get(id))) continue;
    const allClosed = k.every((c) => closed(status.get(c)));
    const anyDone = k.some((c) => status.get(c) === 'Done');
    const newest = k.map((c) => edited.get(c)).sort().pop();
    if (allClosed && anyDone && newest >= edited.get(id)) set(id, 'Done', 'all children closed');
  }
};

down(weekly);
down(tasks);
up(tasks);
up(weekly);

return [...changes.values()].map((json) => ({ json }));

const rows = (name) => $(name).all().map(i => i.json).filter(p => p && p.id && p.properties);
const weekly = rows('Get Weekly Items');
const tasks = rows('Get Tasks');
const subs = rows('Get Subtasks');
const key = (id) => id.replace(/-/g, '');

const staticData = $getWorkflowStaticData('global');
if (!staticData.dueDates) staticData.dueDates = {};
const seen = staticData.dueDates;

const dueDate = (p) => p.properties['Due Date']?.date?.start ?? null;
const timesMoved = (p) => p.properties['Times Moved']?.number ?? 0;
const status = (p) => p.properties.Status?.select?.name ?? null;
const closed = (s) => s === 'Done' || s === 'Cancelled';

const subsByTask = new Map();
for (const s of subs) {
  for (const r of s.properties['Task']?.relation ?? []) {
    const taskId = key(r.id);
    if (!subsByTask.has(taskId)) subsByTask.set(taskId, []);
    subsByTask.get(taskId).push(s);
  }
}

const dayName = (iso) => iso ? DateTime.fromISO(iso).setLocale('en').toFormat('cccc') : null;
const changes = [];

// Compares each item's Due Date to what we saw last sweep (kept in workflow static data, not a Notion column).
// First time an item is seen, its date is only recorded as a baseline -- never counted as a move.
const processItem = (p, table, forcedDueDate) => {
  const id = key(p.id);
  const currentDue = forcedDueDate !== undefined ? forcedDueDate : dueDate(p);
  const prevSeen = seen[id];
  seen[id] = currentDue;
  if (prevSeen === undefined) return false;
  if (prevSeen === currentDue) return false;
  const change = { page_id: p.id, table, due_date: currentDue, times_moved: timesMoved(p) + 1 };
  if (table === 'Weekly Plan') change.day = dayName(currentDue);
  changes.push(change);
  return true;
};

// A Task's date change forces the same new date onto its open Subtasks (and counts as a move for them too).
const processedSubtasks = new Set();
for (const p of weekly) processItem(p, 'Weekly Plan');
for (const p of tasks) {
  const changed = processItem(p, 'Tasks');
  if (changed) {
    const newDue = dueDate(p);
    for (const s of subsByTask.get(key(p.id)) ?? []) {
      if (closed(status(s))) continue;
      processItem(s, 'Subtasks', newDue);
      processedSubtasks.add(key(s.id));
    }
  }
}
for (const p of subs) {
  if (processedSubtasks.has(key(p.id))) continue;
  processItem(p, 'Subtasks');
}

return changes.map((json) => ({ json }));
